<script setup>
import { ref, reactive, computed, watch } from 'vue';
import Icon from '../components/Icon.vue';
import Modal from '../components/Modal.vue';
import AgentShelf from '../components/agents/AgentShelf.vue';
import AgentIndex from '../components/agents/AgentIndex.vue';
import { state, isDemo, nav, notify, report, refresh, launch } from '../lib/workspace.js';
import { strategies } from '../lib/demo.js';
import { post } from '../lib/api.js';
const tab = ref('self'), keyword = ref(''), dialog = ref(''), busy = ref(false), formError = ref(''), detail = ref(null), detailTab = ref('base'), templateOnly = ref(false);
const form = reactive({ agentName: '', agentDesc: '', strategy: 'step', modelId: '', mcpIdSet: [] });
const edit = reactive({ agentName: '', agentDesc: '', modelId: '', mcpIds: [], clientIds: [], plazaTitle: '', plazaDesc: '' });
const visible = computed(() => (state.repo[tab.value] || []).filter(a => (a.agentName + (a.agentDesc || '')).toLowerCase().includes(keyword.value.toLowerCase())));
const canCreate = computed(() => form.agentName.trim() && form.agentDesc.trim() && form.modelId);
// Shelf 只取前 3 条，Index 展示其余，保证同一条数据不在两处重复出现。
const shelfAgents = computed(() => visible.value.slice(0, 3));
const indexAgents = computed(() => visible.value.slice(3));
function openCreate() { Object.assign(form, { agentName: '', agentDesc: '', strategy: 'step', modelId: state.models[0]?.modelId || '', mcpIdSet: [] }); formError.value = ''; dialog.value = 'create'; }
async function create() {
  if (!canCreate.value || busy.value) return; busy.value = true; formError.value = '';
  try {
    const payload = { ...form, agentName: form.agentName.trim(), agentDesc: form.agentDesc.trim(), modelName: state.models.find(m => m.modelId === form.modelId)?.modelName };
    if (isDemo.value) { const agent = { ...payload, agentId: 'demo-agent-' + Date.now(), repoId: 'demo-repo-' + Date.now(), agentType: form.strategy, repoType: 'self', createTime: new Date().toISOString() }; state.repo.self.unshift(agent); state.agents.push(agent); }
    else { await post('/workspace/agent/create', { json: payload }); await refresh(); }
    dialog.value = ''; nav('agents'); tab.value = 'self'; notify(isDemo.value ? '演示智能体已创建，仅保留在当前页面会话中' : '智能体已创建');
  } catch (error) { formError.value = error.message; } finally { busy.value = false; }
}
async function openDetail(agent) {
  formError.value = ''; busy.value = true; dialog.value = 'detail'; detail.value = null; detailTab.value = 'base'; templateOnly.value = agent.repoType === 'favor' || !agent.agentId;
  try {
    const result = isDemo.value ? { ...agent, modelId: state.models[0]?.modelId, modelName: state.models[0]?.modelName, mcpInfoList: state.mcps.slice(0, 1), clientInfoList: (strategies[agent.agentType]?.roles || []).map((role, i) => ({ clientId: 'demo-role-' + i, clientRole: role, promptId: 'demo-prompt-' + i, flowId: i + 1, systemPrompt: `你是${role}角色。请围绕任务目标完成你的职责，并输出清晰、可验证的结论。`, userPrompt: '结合用户目标与已有信息，完成当前阶段。' })) } : await post('/workspace/agent/' + (templateOnly.value ? 'template' : 'detail'), { query: templateOnly.value ? { templateId: agent.templateId } : { agentId: agent.agentId } });
    detail.value = result;
    Object.assign(edit, { agentName: result.agentName || '', agentDesc: result.agentDesc || '', modelId: result.modelId || state.models[0]?.modelId || '', mcpIds: (result.mcpInfoList || []).map(m => m.mcpId), clientIds: (result.clientInfoList || []).map(c => c.clientId), plazaTitle: result.agentName || '', plazaDesc: result.agentDesc || '' });
  } catch (error) { formError.value = error.message; } finally { busy.value = false; }
}
async function savePart(part, json) {
  if (busy.value) return; busy.value = true; formError.value = '';
  try {
    if (!isDemo.value) await post('/workspace/agent/update/' + part, { json: { agentId: detail.value.agentId, ...json } });
    if (part === 'base') { Object.assign(detail.value, json); for (const list of [state.repo.self, state.repo.fork, state.agents]) { const item = list?.find(a => a.agentId === detail.value.agentId); if (item) Object.assign(item, json); } }
    notify(isDemo.value ? '演示配置已更新' : '配置已保存');
  } catch (error) { formError.value = error.message; } finally { busy.value = false; }
}
async function publish() { if (busy.value) return; busy.value = true; try { if (!isDemo.value) await post('/workspace/agent/publish', { json: { agentId: detail.value.agentId, plazaTitle: edit.plazaTitle, plazaDesc: edit.plazaDesc } }); notify(isDemo.value ? '演示发布已提交，不会对外公开' : '发布请求已提交，请稍后在广场刷新确认'); dialog.value = ''; } catch (error) { report(error); } finally { busy.value = false; } }
async function remove() { if (busy.value) return; busy.value = true; try { if (!isDemo.value) await post('/workspace/agent/delete', { query: { agentId: detail.value.agentId } }); else { state.repo.self = state.repo.self.filter(a => a.agentId !== detail.value.agentId); state.repo.fork = state.repo.fork.filter(a => a.agentId !== detail.value.agentId); state.agents = state.agents.filter(a => a.agentId !== detail.value.agentId); } dialog.value = ''; notify(isDemo.value ? '演示智能体已删除' : '删除请求已提交，请稍后刷新确认'); } catch (error) { report(error); } finally { busy.value = false; } }
async function fork() { if (busy.value) return; busy.value = true; try { if (!isDemo.value) await post('/workspace/agent/fork', { query: { templateId: detail.value.templateId } }); else { const agent = { ...detail.value, agentId: 'demo-fork-' + Date.now(), repoId: 'demo-fork-r-' + Date.now(), repoType: 'fork' }; state.repo.fork.unshift(agent); state.agents.push(agent); } dialog.value = ''; notify(isDemo.value ? '已复制演示模板' : '复制请求已提交，请稍后刷新确认'); } catch (error) { report(error); } finally { busy.value = false; } }
watch(() => state.route.params, params => { if (params.create) openCreate(); else if (params.detail) { const agent = Object.values(state.repo).flat().find(a => a.agentId === params.detail); if (agent) openDetail(agent); } }, { immediate: true });
watch(() => state.models, list => { if (!form.modelId) form.modelId = list[0]?.modelId || ''; });
</script>
<template>
  <div class="page agents-page">
    <header class="agents-head">
      <div class="agents-head__copy"><div class="eyebrow">YOUR LITTLE TEAM, BIG POSSIBILITIES</div><h1>我的智能体</h1><p>把重复的工作交给伙伴，把时间留给创造。</p></div>
      <button class="primary-button agents-head__create" @click="openCreate"><Icon name="plus" :size="17" />创建智能体</button>
    </header>
    <div class="agents-toolbar">
      <div class="agents-tabs" role="tablist" aria-label="智能体分类"><button v-for="(label, key) in { self: '我的', fork: '来自团队', favor: '收藏' }" :key="key" type="button" role="tab" :aria-selected="tab === key" :class="{ active: tab === key }" @click="tab = key">{{ label }} <span class="agents-tabs__count">{{ state.repo[key]?.length || 0 }}</span></button></div>
      <div class="agents-toolbar__right"><div class="search-field agents-search"><Icon name="search" :size="16" /><input v-model="keyword" placeholder="搜索你的智能体" aria-label="搜索智能体" /></div><button class="icon-button" aria-label="刷新智能体" @click="refresh"><Icon name="refresh" :size="17" /></button></div>
    </div>
    <div v-if="isDemo" class="demo-notice"><i class="tiny-dot"></i>演示工作空间 · 可创建和编辑示例，刷新页面后重置</div>
    <template v-if="visible.length">
      <section class="agents-shelf" aria-label="精选智能体"><AgentShelf :agents="shelfAgents" :strategies="strategies" @open="openDetail" @run="launch" /></section>
      <section class="agents-index" aria-label="其余智能体"><AgentIndex :agents="indexAgents" :strategies="strategies" :total="visible.length" @open="openDetail" @run="launch" /></section>
    </template>
    <div v-else class="empty-state"><Icon :name="tab === 'favor' ? 'bookmark' : 'bot'" :size="40" /><h2>{{ keyword ? '没有找到这位伙伴' : '给下一位伙伴留个位置' }}</h2><p>{{ keyword ? '换个关键词再试试。' : '创建自己的智能体，或去广场发现更多可能。' }}</p><button class="secondary-button" @click="keyword ? keyword = '' : nav('plaza')">{{ keyword ? '清空搜索' : '探索广场' }}<Icon name="arrow" :size="16" /></button></div>
  </div>
  <Modal v-if="dialog === 'create'" title="认识你的下一位 AI 伙伴" wide @close="!busy && (dialog = '')"><form class="modal-body form-stack" @submit.prevent="create"><div class="info-note">给它一个名字、一项擅长的工作。智能体会根据职责生成角色提示词。</div><div class="form-grid"><label>智能体名称<input v-model="form.agentName" required maxlength="60" placeholder="例如：我的深度研究助手" /></label><label>使用模型<select v-model="form.modelId" required><option value="" disabled>请选择模型</option><option v-for="model in state.models" :key="model.modelId" :value="model.modelId">{{ model.modelName }}</option></select><small v-if="!state.models.length">请先在个人设置中添加模型。</small></label></div><label>它擅长什么？<textarea v-model="form.agentDesc" required rows="3" placeholder="描述它的职责、目标与边界，例如：检索技术资料，交叉验证信息，输出附带来源的研究报告。" /></label><div><p class="field-label">选择思考方式</p><div class="strategy-choices"><button v-for="(strategy, key) in strategies" :key="key" type="button" :class="{ active: form.strategy === key }" @click="form.strategy = key"><Icon :name="strategy.icon" :size="22" /><strong>{{ strategy.label }}</strong><small>{{ strategy.description }}</small></button></div></div><div><p class="field-label">连接工具 · 可选</p><div class="selection-list"><label v-for="mcp in state.mcps" :key="mcp.mcpId" class="checkbox-line"><input v-model="form.mcpIdSet" :value="mcp.mcpId" type="checkbox" />{{ mcp.mcpName }}</label><span v-if="!state.mcps.length" class="muted small">暂无工具，可在设置中添加。</span></div></div><div v-if="formError" class="form-error">{{ formError }}</div><div class="form-actions"><span v-if="busy" class="small muted">正在生成角色提示词，请稍候…</span><button type="button" class="secondary-button" :disabled="busy" @click="dialog = ''">取消</button><button class="primary-button" :disabled="busy || !canCreate"><Icon name="sparkles" :size="17" />{{ busy ? '创建中…' : '创建智能体' }}</button></div></form></Modal>
  <Modal v-if="dialog === 'detail'" :title="detail?.agentName || '智能体详情'" wide @close="!busy && (dialog = '')"><div class="modal-body"><div v-if="busy && !detail" class="loading-placeholder">正在读取配置…</div><template v-if="detail"><div class="detail-overview"><span class="agent-avatar" :class="strategies[detail.agentType]?.color"><Icon :name="strategies[detail.agentType]?.icon" :size="25" /></span><div><h3>{{ detail.agentName }}</h3><p>{{ strategies[detail.agentType]?.label }} · {{ detail.modelName || '未配置模型' }}</p></div><button v-if="!templateOnly" class="primary-button" @click="dialog = ''; launch(detail)"><Icon name="play" :size="15" />开始任务</button><button v-else class="primary-button" :disabled="busy" @click="fork">复制到工作区</button></div><div class="flow-preview"><template v-for="(role, i) in strategies[detail.agentType]?.roles || []" :key="role"><Icon v-if="i" name="arrow" :size="16" /><span><i>{{ i + 1 }}</i>{{ role }}</span></template></div><div class="tabs detail-tabs"><button :class="{ active: detailTab === 'base' }" @click="detailTab = 'base'">基本配置</button><button :class="{ active: detailTab === 'prompts' }" @click="detailTab = 'prompts'">角色与提示词</button></div><div v-if="detailTab === 'base'" class="form-stack"><form class="form-stack" @submit.prevent="savePart('base', { agentName: edit.agentName, agentDesc: edit.agentDesc })"><label>名称<input v-model="edit.agentName" :disabled="templateOnly" required /></label><label>职责描述<textarea v-model="edit.agentDesc" :disabled="templateOnly" required /></label><button v-if="!templateOnly" class="secondary-button" :disabled="busy">保存基本信息</button></form><template v-if="!templateOnly"><div class="editor-divider"></div><label>更新所选角色的模型<select v-model="edit.modelId"><option v-for="model in state.models" :key="model.modelId" :value="model.modelId">{{ model.modelName }}</option></select></label><div><p class="field-label">应用到角色</p><div class="selection-list"><label v-for="client in detail.clientInfoList" :key="client.clientId" class="checkbox-line"><input v-model="edit.clientIds" type="checkbox" :value="client.clientId" />{{ client.clientRole }}</label></div></div><button class="secondary-button" :disabled="busy || !edit.clientIds.length || !edit.modelId" @click="savePart('model', { modelId: edit.modelId, clientIdList: edit.clientIds })">保存所选角色模型</button><div><p class="field-label">连接工具 · 取消全部选择会清空所选角色的工具</p><div class="selection-list"><label v-for="mcp in state.mcps" :key="mcp.mcpId" class="checkbox-line"><input v-model="edit.mcpIds" type="checkbox" :value="mcp.mcpId" />{{ mcp.mcpName }}</label></div></div><button class="secondary-button" :disabled="busy || !edit.clientIds.length" @click="savePart('mcp', { clientIdList: edit.clientIds, mcpIdList: edit.mcpIds })">保存所选角色工具</button><div class="form-actions"><button class="text-button" @click="dialog = 'delete'">删除智能体</button><button class="secondary-button" @click="dialog = 'publish'">发布到广场 <Icon name="external" :size="15" /></button></div></template></div><div v-else class="prompt-editor-list"><details v-for="(client, index) in detail.clientInfoList" :key="client.clientId || index" :open="index === 0"><summary>{{ client.clientRole }}<Icon name="down" :size="16" /></summary><div class="form-stack"><form class="form-stack" @submit.prevent="savePart('systemprompt', { promptId: client.promptId, systemPrompt: client.systemPrompt })"><label>系统提示词<textarea v-model="client.systemPrompt" rows="6" :disabled="templateOnly" required /></label><button v-if="!templateOnly" class="secondary-button" :disabled="busy">保存系统提示词</button></form><form class="form-stack" @submit.prevent="savePart('userprompt', { flowId: client.flowId, userPrompt: client.userPrompt })"><label>用户提示词模板<textarea v-model="client.userPrompt" rows="4" :disabled="templateOnly" required /></label><button v-if="!templateOnly" class="secondary-button" :disabled="busy">保存用户提示词</button></form></div></details><div v-if="!detail.clientInfoList?.length" class="empty-inline">没有可编辑的角色提示词。</div></div></template><div v-if="formError" class="form-error">{{ formError }}</div></div></Modal>
  <Modal v-if="dialog === 'publish'" title="把好伙伴分享给更多人" @close="!busy && (dialog = '')"><form class="modal-body form-stack" @submit.prevent="publish"><label>发布标题<input v-model="edit.plazaTitle" required /></label><label>介绍它的能力<textarea v-model="edit.plazaDesc" required /></label><div class="info-note">发布后，其他用户可以查看和复制该智能体模板。发布会异步处理。</div><button class="primary-button" :disabled="busy">{{ busy ? '正在提交…' : '确认发布到广场' }}</button></form></Modal>
  <Modal v-if="dialog === 'delete'" title="删除这个智能体？" @close="!busy && (dialog = '')"><div class="modal-body form-stack"><p class="muted small">「{{ detail.agentName }}」将从你的工作区删除，此操作无法恢复。</p><button class="danger-button" :disabled="busy" @click="remove">确认删除</button></div></Modal>
</template>
